p=argparse.ArgumentParser();p.add_argument('--arm',choices=['candidate-v13.7','baseline-v12.6-common-4'],required=True);p.add_argument('--case',choices=['ios-unsupported-query-resolution','android-provider-string-is-not-query-proof','ios-cycle-not-complete-native-query','android-cycle-not-complete-native-query','ios-same-entity-duplicate-record','android-same-entity-duplicate-record','ios-query-header-missing-conflicts-with-native-tree','ios-local-complete-query-absence','android-local-complete-query-absence'],required=True);a=p.parse_args();root=Path(__file__).resolve().parents[1];sys.path.insert(0,str(root.parents[1]/a.arm/'scripts'));import native_checks
group='query-additive'if'local-complete-query'in a.case else'query';base=root/'work'/a.arm/group/a.case;load=lambda p:json.loads(p.read_text());o=load(base/'observation.json');plan=load(base/'plan.json');platform='android'if a.case.startswith('android')else'ios';native=base/('native'if platform=='android'else'packet/native');report=native_checks.evaluate(plan,o,platform,root=native);selector=plan['assertions'][0]['target'];print(json.dumps({'evidence_class':'HOST read-only evaluation of SIMULATED original query fixture','state':report['states'],'actual_native_node_matches':[sum(native_checks.same_selector(n,selector)for n in snap['nodes'])for snap in o['snapshots']],'group_match_counts':[[g.get('match_count')for g in snap.get('control_groups',[])if g.get('selector')==selector]for snap in o['snapshots']],'query_complete':[native_checks.native_query_complete(snap,selector,platform)for snap in o['snapshots']],'assertion':report['assertions'][0]},indent=2))
